static void Require(bool ok,const char* s){if(!ok)throw std::runtime_error(s);}
static void Check(HRESULT hr,const char*s){if(FAILED(hr)){std::fprintf(stderr,"%s hr=%08lx\n",s,(unsigned long)hr);throw std::runtime_error(s);}}
template<class T>struct Com{T*p=nullptr;~Com(){if(p)p->Release();}T**out(){return &p;}T*operator->(){return p;}};
using Factory=HRESULT(WINAPI*)(REFCLSID,REFIID,void**);
static Factory factory; static bool registeredMode=false;
static void Create(const wchar_t*id,REFIID iid,void**p){CLSID c;Check(CLSIDFromString(id,&c),"CLSID");if(registeredMode){Check(CoCreateInstance(c,nullptr,CLSCTX_INPROC_SERVER,iid,p),"registered CoCreateInstance");return;}Com<IClassFactory>f;Check(factory(c,IID_IClassFactory,(void**)f.out()),"factory");Check(f->CreateInstance(nullptr,iid,p),"create");}
static void Modules(int major,HMODULE original){HMODULE clr=GetModuleHandleW(L"coreclr.dll");Require(clr==original,"host CLR changed");if(major){wchar_t path[32768];Require(clr&&GetModuleFileNameW(clr,path,32768),"host CLR missing");Require(std::wstring(path).find(L"\\"+std::to_wstring(major)+L".")!=std::wstring::npos,"wrong host CLR major");std::wprintf(L"CORECLR %ls\n",path);}else Require(!clr,"native host acquired CLR");HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE,GetCurrentProcessId());Require(snap!=INVALID_HANDLE_VALUE,"module snapshot");MODULEENTRY32W entry{};entry.dwSize=sizeof(entry);BOOL more=Module32FirstW(snap,&entry);bool clean=true;while(more){std::wstring name=entry.szModule;for(auto&c:name)c=towlower(c);if(name==L"apkshellext2.dll"||name.find(L"skia")!=std::wstring::npos||name==L"apkshellext2.comhost.dll")clean=false;more=Module32NextW(snap,&entry);}CloseHandle(snap);Require(clean,"managed extension/Skia/comhost loaded in host");}
static void WriteRename(const std::wstring&path){HANDLE h=CreateFileW(path.c_str(),GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,0,nullptr);Require(h!=INVALID_HANDLE_VALUE,"source write blocked while COM alive");DWORD n=0;bool ok=WriteFile(h,"P",1,&n,nullptr)!=0;CloseHandle(h);Require(ok&&n==1,"source write failed");auto next=path+L".renamed";Require(MoveFileW(path.c_str(),next.c_str()),"source rename blocked while COM alive");Require(MoveFileW(next.c_str(),path.c_str()),"restore source filename");HANDLE reset=CreateFileW(path.c_str(),GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,TRUNCATE_EXISTING,0,nullptr);Require(reset!=INVALID_HANDLE_VALUE,"reset empty source");CloseHandle(reset);}
static void Icon(const wchar_t*path,bool failure,bool mutate){Com<IExtractIconW> icon;Create(L"{1F869CEE-4FDA-35D9-896F-43975A87D1F6}",IID_IExtractIconW,(void**)icon.out());Com<IPersistFile>file;Check(icon->QueryInterface(IID_IPersistFile,(void**)file.out()),"icon persist");Check(file->Load(path,STGM_READ),"icon load");wchar_t location[260];int index;UINT flags;Check(icon->GetIconLocation(0,location,260,&index,&flags),"icon location");HICON large=nullptr,small=nullptr;auto start=GetTickCount64();HRESULT hr=icon->Extract(path,index,&large,&small,MAKELONG(64,32));auto elapsed=GetTickCount64()-start;bool valid=large&&small;for(HICON h:{large,small})if(h){ICONINFO ii{};Require(GetIconInfo(h,&ii),"icon bitmap");BITMAP bm{};GetObjectW(ii.hbmColor,sizeof(bm),&bm);if(!failure)Require(bm.bmWidth==(h==large?64:32),"icon dimensions");DeleteObject(ii.hbmColor);DeleteObject(ii.hbmMask);DestroyIcon(h);}if(!failure){Check(hr,"icon extract");Require(valid,"missing icons");}else {Require(elapsed<19000,"fault not bounded");std::printf("FAULT icon hr=%08lx elapsed=%llu ms\n",(unsigned long)hr,elapsed);}if(mutate)WriteRename(path);std::puts("PASS icon 64/32 and source lifetime");}
static void Info(const wchar_t*path,bool failure){Com<IQueryInfo>info;Create(L"{946435a5-fe96-416d-99db-e94ee9fb46c8}",IID_IQueryInfo,(void**)info.out());Com<IPersistFile>file;Check(info->QueryInterface(IID_IPersistFile,(void**)file.out()),"info persist");Check(file->Load(path,STGM_READ),"info load");LPWSTR text=nullptr;HRESULT hr=info->GetInfoTip(0,&text);bool valid=text&&*text;if(text)CoTaskMemFree(text);if(!failure){Check(hr,"info tip");Require(valid,"empty info");}std::puts("PASS info callback");}
static void Thumbnail(const wchar_t*path,int failure){Com<IInitializeWithStream>init;Create(L"{d747c5a7-2f66-4b7d-8301-8531838e4ed3}",__uuidof(IInitializeWithStream),(void**)init.out());Com<IThumbnailProvider>thumb;Check(init->QueryInterface(__uuidof(IThumbnailProvider),(void**)thumb.out()),"thumbnail QI");Com<IStream>source;Check(SHCreateStreamOnFileEx(path,STGM_READ|STGM_SHARE_DENY_NONE,FILE_ATTRIBUTE_NORMAL,FALSE,nullptr,source.out()),"stream");Check(init->Initialize(source.p,STGM_READ),"initialize stream");HBITMAP b=nullptr;WTS_ALPHATYPE alpha=WTSAT_UNKNOWN;HRESULT hr=thumb->GetThumbnail(64,&b,&alpha);bool valid=b!=nullptr;if(b)DeleteObject(b);if(!failure){Check(hr,"thumbnail");Require(valid&&alpha==WTSAT_ARGB,"thumbnail bitmap/alpha");}if(failure==2)Require(FAILED(hr)&&!valid,"disabled thumbnail unexpectedly produced bitmap");std::puts(failure==2?"PASS disabled thumbnail returns failure/no bitmap":"PASS stream thumbnail callback");}
static void Context(const wchar_t*path){Com<IShellExtInit>init;Create(L"{dcb629fc-f86f-456f-8e24-98b9b2643a9b}",IID_IShellExtInit,(void**)init.out());Com<IContextMenu>menu;Check(init->QueryInterface(IID_IContextMenu,(void**)menu.out()),"context QI");PIDLIST_ABSOLUTE item=nullptr;Check(SHParseDisplayName(path,nullptr,&item,0,nullptr),"context pidl");Com<IDataObject>data;PIDLIST_ABSOLUTE parent=ILCloneFull(item);Require(parent&&ILRemoveLastID(parent),"context parent");PCUITEMID_CHILD child=ILFindLastID(item);HRESULT dataHr=SHCreateDataObject(parent,1,&child,nullptr,IID_IDataObject,(void**)data.out());CoTaskMemFree(parent);CoTaskMemFree(item);Check(dataHr,"context data");Check(init->Initialize(nullptr,data.p,nullptr),"context initialize");HMENU h=CreatePopupMenu();HRESULT hr=menu->QueryContextMenu(h,0,1,100,CMF_NORMAL);int count=GetMenuItemCount(h);DestroyMenu(h);Check(hr,"query menu");Require(HRESULT_CODE(hr)>0&&count>0,"empty context menu");std::puts("PASS context initialized menu");}
extern "C" __declspec(dllexport) int __cdecl RunIsolation(const wchar_t*bridge,const wchar_t*apk,int major,int failure){registeredMode=(failure&4)!=0;failure&=3;HRESULT co=CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);if(FAILED(co))return 2;HMODULE dll=nullptr;std::wstring empty;try{HMODULE clr=GetModuleHandleW(L"coreclr.dll");Modules(major,clr);if(!registeredMode){dll=LoadLibraryExW(bridge,nullptr,LOAD_WITH_ALTERED_SEARCH_PATH);Require(dll,"LoadLibrary bridge");factory=(Factory)GetProcAddress(dll,"DllGetClassObject");Require(factory,"factory export");}if(failure!=1){wchar_t dir[MAX_PATH],name[MAX_PATH];Require(GetTempPathW(MAX_PATH,dir)&&GetTempFileNameW(dir,L"ais",0,name),"temp source");empty=std::wstring(name)+L".apk";Require(MoveFileW(name,empty.c_str()),"temp apk");if(registeredMode){SHFILEINFOW sh{};Require(SHGetFileInfoW(empty.c_str(),0,&sh,sizeof(sh),SHGFI_ICON|SHGFI_LARGEICON)!=0&&sh.hIcon,"registered SHGetFileInfo empty APK");DestroyIcon(sh.hIcon);WriteRename(empty);std::puts("PASS registered SHGetFileInfo empty download write/rename");}Icon(empty.c_str(),false,true);DeleteFileW(empty.c_str());}Icon(apk,failure==1,false);Info(apk,failure==1);Thumbnail(apk,failure);Context(apk);Modules(major,clr);HMODULE actual=registeredMode?GetModuleHandleW(L"ApkShellext2.Native.dll"):dll;wchar_t actualPath[32768]={};Require(actual&&GetModuleFileNameW(actual,actualPath,32768),"native module missing");Require(_wcsicmp(actualPath,bridge)==0,"registered native module differs from expected candidate");std::wprintf(L"NATIVE %ls\n",actualPath);auto unload=(HRESULT(WINAPI*)())GetProcAddress(actual,"DllCanUnloadNow");Require(unload,"missing unload export");if(!registeredMode)Require(unload()==S_OK,"COM references leaked");if(dll)FreeLibrary(dll);CoUninitialize();std::puts("PASS isolation host and callbacks");return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL %s error=%lu\n",e.what(),GetLastError());if(!empty.empty())DeleteFileW(empty.c_str());if(dll)FreeLibrary(dll);CoUninitialize();return 1;}}
#ifndef ISOLATION_DLL
int wmain(int argc,wchar_t**argv){if(argc<3)return 2;int mode=0;for(int i=3;i<argc;++i){std::wstring a=argv[i];if(a==L"--registered")mode|=4;else if(a==L"--disabled")mode|=2;else if(a==L"--fault")mode|=1;else return 2;}return RunIsolation(argv[1],argv[2],0,mode);}
#endif
